const VENEZUELA_PAUSED = true; // luto — no reactivar sin confirmación explícita

const AGENT_ROUTING = {
  'venezuela': {
    agent_id: 'agent_5801kt2n54gne8s8dwgb03sbwf02',
    agent_phone_number_id: 'phnum_3801kvb0m1wqfjh8qqcsh24gfarj',
    language: 'es', endpoint: 'twilio'
  },
  'mexico': {
    agent_id: 'agent_5801kt2n54gne8s8dwgb03sbwf02',
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6',
    language: 'es', endpoint: 'sip-trunk'
  },
  'colombia': {
    agent_id: 'agent_5801kt2n54gne8s8dwgb03sbwf02', // mismo agente de Venezuela, por instrucción
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6', // <-- REEMPLAZAR: phone_number_id del número CO registrado en ElevenLabs (Technologia Hub)
    language: 'es', endpoint: 'twilio'
  },
  'default': {
    agent_id: 'agent_9301ktxas162fypr684x98x2gcrn',
    agent_phone_number_id: 'phnum_1601kv7bh3y9fxmtdzesa3vcfr76',
    language: 'es', endpoint: 'sip-trunk'
  }
};
function resolveAgent(country) {
  return AGENT_ROUTING[country] || AGENT_ROUTING['default'];
}

function toE164(raw) {
  if (raw === undefined || raw === null) return '';
  let p = String(raw).replace(/[^0-9+]/g, '');
  if (!p) return '';
  if (p.startsWith('+')) return p;
  if (p.length >= 8 && p.length <= 15) return '+' + p;
  return '';
}

const SKIP_STATUSES = new Set([
  'DO_NOT_CALL', 'CONVERTED', 'MAX_ATTEMPTS_REACHED',
  'INTERESTED', 'NOT_INTERESTED', 'SALES_HANDOFF', 'ACCOUNT_OPENED'
]);

// Países habilitados HOY. Venezuela queda fuera hasta reactivación explícita.
const ACTIVE_COUNTRIES = new Set(['mexico', 'colombia']);

// Ventana de llamada por país (hora local, 24h). Ajusta si hace falta.
//const CALLING_WINDOWS = {
//  mexico:   { tzOffset: -6, startHour: 11, endHour: 21 }, // CST
//  colombia: { tzOffset: -5, startHour: 9,  endHour: 20 }  // COT
//};

//function isCountryActiveNow(country) {
//  const win = CALLING_WINDOWS[country];
//  if (!win) return true;
//  const nowUTC = new Date();
//  const localHour = (nowUTC.getUTCHours() + win.tzOffset + 24) % 24;
//  return localHour >= win.startHour && localHour < win.endHour;
//}

const MAX_ATTEMPTS = 3;
const COOLDOWN_HOURS = 24;
const CALL_TIMEOUT_MIN = 30;
const PER_COUNTRY = 10;
const BATCH_SIZE = 5; // 5 por país x 2 países activos
const now = Date.now();

const attempts = [];
const skipped = [];

for (const item of $input.all()) {
  const r = { ...(item.json || {}) };
  const phone = toE164(r.phone);
  let attemptsCount = Number(r.call_attempts || 0);
  let status = String(r.status || '').trim().toUpperCase();

  if (!phone) { skipped.push({ lead_id: r.lead_id, reason: 'bad phone' }); continue; }
  if (!r.lead_id || String(r.lead_id).trim() === '') { skipped.push({ lead_id: 'EMPTY', reason: 'missing lead_id' }); continue; }

  const phoneStr = String(phone);
  let country = String(r.country || '').trim().toLowerCase();
  if (!country || country.length < 2) {
    if (phoneStr.startsWith('+58'))  country = 'venezuela';
    else if (phoneStr.startsWith('+57')) country = 'colombia';
    else if (phoneStr.startsWith('+52')) country = 'mexico';
    else country = 'mexico';
  }
  r.country = country;

  if (country === 'venezuela' && VENEZUELA_PAUSED) {
    skipped.push({ lead_id: r.lead_id, reason: 'VZ_PAUSED — luto nacional' }); continue;
  }
  if (!ACTIVE_COUNTRIES.has(country)) {
    skipped.push({ lead_id: r.lead_id, reason: `country ${country} no habilitado` }); continue;
  }
  //if (!isCountryActiveNow(country)) {
  //  skipped.push({ lead_id: r.lead_id, reason: `${country} fuera de horario` }); continue;
  //}

  if (status === 'INVALID_LEAD') {
    status = 'READY_TO_CALL'; r.status = 'READY_TO_CALL';
    r.call_attempts = 0; attemptsCount = 0;
  }

  if ((status === 'CALL_IN_PROGRESS' || status === 'DIALING') && r.last_call_time) {
    const minsSince = (now - new Date(r.last_call_time).getTime()) / 60000;
    if (minsSince > CALL_TIMEOUT_MIN) {
      status = 'READY_TO_CALL'; r.status = 'READY_TO_CALL';
    } else {
      skipped.push({ lead_id: r.lead_id, reason: `${status} ${minsSince.toFixed(0)}min` }); continue;
    }
  }

  if (status === 'DIAL_FAILED') {
    if (r.last_call_time) {
      const hoursSince = (now - new Date(r.last_call_time).getTime()) / 3600000;
      if (hoursSince < COOLDOWN_HOURS) {
        skipped.push({ lead_id: r.lead_id, reason: `DIAL_FAILED cooldown ${hoursSince.toFixed(1)}h` }); continue;
      }
    }
    status = 'READY_TO_CALL'; r.status = 'READY_TO_CALL';
  }

  if (attemptsCount >= MAX_ATTEMPTS) {
    if (status !== 'MAX_ATTEMPTS_REACHED') r.status = 'MAX_ATTEMPTS_REACHED';
    skipped.push({ lead_id: r.lead_id, reason: `MAX_ATTEMPTS (${attemptsCount})` }); continue;
  }

  if (attemptsCount > 0 && r.last_call_time) {
    const hoursSince = (now - new Date(r.last_call_time).getTime()) / 3600000;
    if (hoursSince < COOLDOWN_HOURS) {
      skipped.push({ lead_id: r.lead_id, reason: `cooldown ${hoursSince.toFixed(1)}h` }); continue;
    }
  }

  if (SKIP_STATUSES.has(status)) {
    skipped.push({ lead_id: r.lead_id, reason: `status=${status}` }); continue;
  }

  if (status === 'SCHEDULED' && r.callback_date) {
    if (new Date(r.callback_date).getTime() > now) {
      skipped.push({ lead_id: r.lead_id, reason: 'scheduled for later' }); continue;
    }
  }

  r.phone = phone;
  r.full_name = String(r.full_name || '').trim() || 'User';
  r.lead_id = String(r.lead_id).trim();

  const _agent = resolveAgent(country);
  r.agent_id = _agent.agent_id;
  r.agent_phone_number_id = _agent.agent_phone_number_id;
  r.language = _agent.language;
  r.endpoint = _agent.endpoint;

  attempts.push({ json: r });
}

console.log(`🟢 Elegibles: ${attempts.length} | skipped: ${skipped.length}`);
console.log(`🔒 ACTIVE_COUNTRIES: ${[...ACTIVE_COUNTRIES].join(',')} | VZ_PAUSED:${VENEZUELA_PAUSED}`);

if (attempts.length === 0) return [];

const byCountry = {};
for (const a of attempts) {
  const c = a.json.country || 'default';
  (byCountry[c] = byCountry[c] || []).push(a);
}
let batch = [];
for (const c of Object.keys(byCountry)) {
  batch = batch.concat(byCountry[c].slice(0, PER_COUNTRY));
}
batch = batch.slice(0, BATCH_SIZE);
console.log(`📦 Batch: ${batch.length} (máx ${BATCH_SIZE}, ${PER_COUNTRY}/país)`);
return batch;

